package com.xpdustry.shard.content.load;

import com.xpdustry.shard.content.schema.*;
import com.xpdustry.shard.content.yaml.*;

import java.util.*;

/**
 * A content pack: a schema, the wire id order, and prototype files in load order. The vanilla pack is generated by
 * {@code :tools:content-extract} into {@code content/vanilla/}; a world adds overlay files on top of it.
 *
 * @param name a label for diagnostics
 * @param files prototype files, in load order
 */
public record Pack(String name, Schema schema, Ids ids, List<Source> files){
    /** One YAML file: its path (shown in diagnostics) and text. */
    public record Source(String path, String text){
    }

    public Pack{
        files = List.copyOf(files);
    }

    private static volatile Pack vanilla;

    /** The vanilla v160.7 pack on the class path. */
    public static Pack vanilla(){
        Pack p = vanilla;
        if(p == null){
            synchronized(Pack.class){
                p = vanilla;
                if(p == null) vanilla = p = resource("content/vanilla/");
            }
        }
        return p;
    }

    /** The pack whose {@code pack.yml} is at {@code dir} on the class path; its schema must be the vanilla one. */
    static Pack resource(String dir){
        var diagnostics = new Diagnostics();
        String manifestPath = dir + "pack.yml";
        Node manifest = YamlReader.read(manifestPath, Schema.resource(manifestPath), diagnostics);
        diagnostics.check();
        if(!(manifest instanceof Node.Mapping m) || !(m.get("files") instanceof Node.Sequence list)){
            throw new IllegalStateException(manifestPath + " needs a files list");
        }
        String idsPath = dir + text(m, "ids");
        Ids ids = Ids.read(YamlReader.read(idsPath, Schema.resource(idsPath), diagnostics), diagnostics);
        List<Source> files = new ArrayList<>();
        for(Node n : list.items()){
            String path = dir + ((Node.Scalar)n).value();
            files.add(new Source(path, Schema.resource(path)));
        }
        diagnostics.check();
        return new Pack("vanilla " + text(m, "vanilla"), Schema.vanilla(), ids, files);
    }

    private static String text(Node.Mapping m, String key){
        return m.get(key) instanceof Node.Scalar s ? s.value() : null;
    }

    /** This pack with {@code overlays} loaded after its own files. */
    public Pack with(List<Source> overlays){
        List<Source> all = new ArrayList<>(files);
        all.addAll(overlays);
        return new Pack(name, schema, ids, all);
    }

    /** The total UTF-8 size of the prototype files, for reports. */
    public long bytes(){
        long n = 0;
        for(Source s : files) n += s.text().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
        return n;
    }
}
